"""Package the owner's PixelLab ZIP unchanged; derive navigation, never repaint its art."""
import base64,hashlib,json,shutil
from pathlib import Path
from PIL import Image
import numpy as np

ROOT=Path(__file__).resolve().parents[1];SRC=ROOT/'pixellab-pip-generations/dawn-manual-20261020';DEST=ROOT/'assets/dawn-manual';DEST.mkdir(parents=True,exist_ok=True)
meta=json.loads((SRC/'map.json').read_text());objects=json.loads((SRC/'objects/manifest.json').read_text())['objects'];cfg=meta['mapConfig'];box=cfg['boundingBox'];tile=cfg['tileSize'];offset=(-box['minX']*tile,-box['minY']*tile)
im=Image.open(SRC/'map-composite.png').convert('RGBA');w,h=im.size;assert (w,h)==(cfg['dimensions']['pixelWidth'],cfg['dimensions']['pixelHeight']) and tile==64
# Keep the exported composite byte-for-byte, including the owner's inpainting overlay.
shutil.copyfile(SRC/'map-composite.png',DEST/'map.png');shutil.copyfile(SRC/'terrain-tiles/terrain-1.png',DEST/'water.png')
grid={};letters={'.':0,'á':1,'a':2,'g':4,'e':3,'c':5}
for entry in json.loads((SRC/'terrain-cells.json').read_text(encoding='utf-8'))['rows']:
 row=entry['cells'];assert len(row)==cfg['dimensions']['width'];grid[entry['y']]=[letters[c] for c in row]
assert len(grid)==cfg['dimensions']['height'] and sum(c!=0 for row in grid.values() for c in row)==2141
rgb=np.array(im);r,g,b=(rgb[:,:,i].astype(np.int16) for i in range(3))
water=(b>r+20)&(g>r+15)&(b>65)
land=(~water)&(rgb[:,:,3]>200)
# Color classification is bounded by the source terrain graph: offshore details cannot
# create navigable islands. Native boat hulls are blocked by their full exported bounds.
cells=np.array([grid[y] for y in range(box['minY'],box['maxY']+1)]);near=np.zeros(cells.shape,dtype=bool)
for dy in [-1,0,1]:
 for dx in [-1,0,1]:
  yy,xx=np.indices(cells.shape);sample=cells[np.clip(yy+dy,0,cells.shape[0]-1),np.clip(xx+dx,0,cells.shape[1]-1)];near|=(sample!=0)&(sample!=1)
land &= np.repeat(np.repeat(near,tile,axis=0),tile,axis=1)
step=4;small=land.reshape(h//step,step,w//step,step).mean(axis=(1,3))>=.5
props=[];hashes={};counts={}
for o in objects:
 if not o.get('visible',True):continue
 source=SRC/'objects'/o['filename'];digest=hashlib.sha256(source.read_bytes()).hexdigest();sprite=Image.open(source);size=sprite.size
 if digest not in hashes:
  hashes[digest]=f'object-{len(hashes)}.png';shutil.copyfile(source,DEST/hashes[digest])
 kind={(84,141):'boat',(95,105):'tree',(121,119):'house',(20,80):'lamp',(18,18):'chest'}[size];counts[kind]=counts.get(kind,0)+1
 bb=o['boundingBox'];gb=o['groundBounds'];bounds={k:bb[k]+(offset[0] if k=='x' else offset[1] if k=='y' else 0) for k in bb};foot={k:gb[k]+(offset[0] if k=='x' else offset[1] if k=='y' else 0) for k in gb}
 props.append({'id':o['id'],'kind':kind,'url':'assets/dawn-manual/'+hashes[digest],'bounds':bounds,'foot':foot,'y':foot['y']+foot['height'],'layer':o['layer']})
data={'source':{'map_id':meta['mapId'],'name':meta['name'],'export_date':meta['exportDate'],'sha256':hashlib.sha256((SRC/'map-composite.png').read_bytes()).hexdigest()},'width':w,'height':h,'tile':tile,'cols':w//tile,'rows':h//tile,'offset':{'x':offset[0],'y':offset[1]},'mask':{'step':step,'cols':w//step,'rows':h//step,'bits':base64.b64encode(np.packbits(small.reshape(-1),bitorder='little').tobytes()).decode()},'props':props}
(ROOT/'dawn-map-data.js').write_text("'use strict';\n/* Owner's exported art and ground bounds; generated by tools/import_dawn_manual.py. */\n((r)=>{r.MareDawnData="+json.dumps(data,ensure_ascii=False,separators=(',',':'))+";if(typeof module!=='undefined')module.exports=r.MareDawnData;})(globalThis);\n",encoding='utf-8')
receipt=json.loads((SRC/'source-archive.json').read_text(encoding='utf-8'))
(DEST/'provenance.json').write_text(json.dumps({'source':data['source'],'source_archive':{k:receipt[k] for k in ['filename','sha256']},'native_dimensions':[w,h],'new_generations':0,'art_processing':'Original composite and five unique object PNGs copied byte-for-byte; navigation mask derived from exported pixels, bounded by source terrains. Exported ground bounds are used for obstacles, with full bounds for boats. Runtime fills only unpainted transparent space with the original water tile.','source_objects':len(props),'object_counts':counts,'unique_source_sprites':hashes},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'dimensions':[w,h],'objects':counts,'walk_mask_cells':int(small.sum()),'unique_sprites':len(hashes)}))
